import { useEffect } from "react"
import { connect } from 'react-redux'
import { Table } from 'antd'

import ClaimActions from '../.././../../redux/claims/actions'
import moment from "moment"

import { Container } from './index.style'

const { getInstantListing,resetReduxStateClaim } = ClaimActions


function InstantClaimConfigurationListing(props) {

  const {
    getInstantListing,
    onViewAutoApprovalConfig,
    claimsInstantConfigurationList,
  } = props

  useEffect(() => {
    getInstantListing()
  }, [getInstantListing])



  const listingColumns = [
    {
      title: 'Action',
      dataIndex: 'config_id',
      key: 'config_id',
      render: (config_id) => (<div><div onClick={() => onViewAutoApprovalConfig(config_id)}>View</div>/<a href={`add-instant-claim-configuration?configId=${config_id}`}>Edit</a></div>)
    },
    {
      title: 'Created At',
      dataIndex: 'created_at',
      key: 'created_by',
      render: (createdAt) => {
        return createdAt ? moment(createdAt).format('DD/MM/YYYY HH:mm:ss') : '-'
      }
    },
    {
      title: 'Created By',
      dataIndex: 'created_by',
      key: 'config_id',
    },
    {
      title: 'Configuration ID',
      dataIndex: 'config_id',
      key: 'config_id',
    },
    {
      title: 'Partner Product',
      dataIndex: 'partner_product_key',
      key: 'partner_product_key',
      render: (partner) => {
        if (Array.isArray(partner)) {
          return partner.join(', ')
        }
        return partner
      }
    },
    {
      title: 'Last Modified',
      dataIndex: 'updated_at',
      key: 'updated_at',
      render: (updatedAt) => {
        return updatedAt ? moment(updatedAt).format('DD/MM/YYYY HH:mm:ss') : '-'
      }
    },
    {
      title: 'Insurance Provider',
      dataIndex: 'insurance_provider',
      key: 'insurance_provider',
    },

  ]

  return (
    <Container>
      <Table
        columns={listingColumns}
        dataSource={claimsInstantConfigurationList}
      />
    </Container>
  )

}

const mapStateToProps = (state) => ({
  claimsInstantConfigurationList: state.Claims.claimsInstantConfigurationList
})

export default connect(mapStateToProps, { getInstantListing,resetReduxStateClaim })(InstantClaimConfigurationListing)