import { Button } from "antd"
import { withRouter } from 'react-router'

import { Container } from './index.style'

function AddConfiguration(props) {

  const onClickAddConfiguration = () => {
    const { history } = props

    history.push('add-instant-claim-configuration')
  }

  return (
    <Container>
      <Button type="primary"
      onClick={onClickAddConfiguration}
      >
        Add Configuration
      </Button>
    </Container>
  )

}

export default withRouter(AddConfiguration)