import { useEffect, useState } from 'react'
import { connect } from 'react-redux'
import { Modal, Spin } from 'antd'
import AddConfiguration from './AddConfigurationButton'
import InstantClaimConfigurationListing from './InstantClaimConfigurationListing'

import ClaimActions from '../../../redux/claims/actions'

import { Title, QuestionWrapper } from './index.style'
import moment from 'moment-timezone'

const { getAutoApprovalConfigInfo, resetReduxStateClaim } = ClaimActions

function InstantClaimConfiguration (props) {
  const {
    autoApprovalConfigData = {},
    getAutoApprovalConfigInfo,
    autoApprovalConfigDataLoading,
    resetReduxStateClaim
  } = props

  const { auto_approval_configs: autoApprovalConfigs = {} } = autoApprovalConfigData
  const [selectedConfigIdToView, setSelectedConfigIdToView] = useState(undefined)

  const { config_dump_data: configDumpData = {} } = autoApprovalConfigs
  const { questions = [] } = configDumpData

  const flatOutQuestions = []
  questions.forEach((ques) => {
    flatOutQuestions.push(ques)

    Object.keys(ques.child_questions).forEach((key) => {
      flatOutQuestions.push(ques.child_questions[key])
    })
  })

  useEffect(() => {
    if (selectedConfigIdToView) {
      const query = {
        auto_approval_config_id: selectedConfigIdToView
      }
      getAutoApprovalConfigInfo({ query })
    }
  }, [selectedConfigIdToView, getAutoApprovalConfigInfo])

  useEffect(() => {
    if (!selectedConfigIdToView) {
      resetReduxStateClaim(['autoApprovalConfigData'])
    }
  }, [selectedConfigIdToView, resetReduxStateClaim])

  const onViewAutoApprovalConfig = (configId) => {
    setSelectedConfigIdToView(configId)
  }

  const handleCloseModal = () => {
    setSelectedConfigIdToView(undefined)
  }

  return (
    <div>
      <Title>List of Instant Claim Configuration</Title>
      <AddConfiguration />
      <InstantClaimConfigurationListing
        onViewAutoApprovalConfig={onViewAutoApprovalConfig}
      />

      <Modal
        title='Instanst Claim Configuration Info'
        visible={!!selectedConfigIdToView && Object.keys(autoApprovalConfigData).length}
        onCancel={handleCloseModal}
        onOk={handleCloseModal}
      >
        <Spin spinning={autoApprovalConfigDataLoading}>
          <>
            <QuestionWrapper>
              <div>Insurance Provider: </div>
              <div>{autoApprovalConfigs.insurance_provider || 'N/A'}</div>
            </QuestionWrapper>
            <QuestionWrapper>
              <div>Partner Product: </div>
              <div>
                {
                  autoApprovalConfigs.partner_product_key && Array.isArray(autoApprovalConfigs.partner_product_key)
                    ? autoApprovalConfigs.partner_product_key.join(',')
                    : 'N/A'
                }
              </div>
            </QuestionWrapper>
            <QuestionWrapper>
              <div>Config Id: </div>
              <div>{autoApprovalConfigs.config_id || 'N/A'}</div>
            </QuestionWrapper>
            <QuestionWrapper>
              <div>Created at: </div>
              <div>
                {autoApprovalConfigs.created_at ? moment(autoApprovalConfigs.created_at).format('YYYY-MM-DD') : 'N/A'}
              </div>
            </QuestionWrapper>
            <QuestionWrapper>
              <div>End at: </div>
              <div>
                {autoApprovalConfigs.end_date ? moment.utc(autoApprovalConfigs.end_date).format('YYYY-MM-DD') : 'N/A'}
              </div>
            </QuestionWrapper>
            <QuestionWrapper>
              <div>Created By: </div>
              <div>{autoApprovalConfigs.created_by || 'N/A'}</div>
            </QuestionWrapper>
            <QuestionWrapper>
              <div>Provider POC Email Id: </div>
              <div>{autoApprovalConfigs.provider_poc_email_ids || 'N/A'}</div>
            </QuestionWrapper>
            <QuestionWrapper>
              <div>Updated at:</div>
              <div>{autoApprovalConfigs.updated_at ? moment(autoApprovalConfigs.updated_at).format('YYYY-MM-DD') : 'N/A'}</div>
            </QuestionWrapper>
          </>
        </Spin>
      </Modal>

    </div>
  )
}

const mapSateToProps = (state) => ({
  autoApprovalConfigData: state.Claims.autoApprovalConfigData,
  autoApprovalConfigDataLoading: state.Loading.GET_AUTO_APPROVAL_CONFIG_INFO
})

export default connect(mapSateToProps, { getAutoApprovalConfigInfo, resetReduxStateClaim })(InstantClaimConfiguration)
